import{_ as t,o as e,c as s,a5 as d}from"./chunks/framework.DJo0M80U.js";const b=JSON.parse('{"title":"58. 编译器标志和优化级别","description":"The Little Book of C 中文版 — 58. 编译器标志和优化级别","frontmatter":{"title":"58. 编译器标志和优化级别","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","06-编译与构建","中文"],"description":"The Little Book of C 中文版 — 58. 编译器标志和优化级别","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":58,"sidebarWeight":58,"alternateZh":"/posts/c教程/zh-CN/06-编译与构建/058-Compiler Flags and Optimization Levels","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/058-Compiler Flags and Optimization Levels"},"headers":[],"relativePath":"posts/c教程/zh-CN/06-编译与构建/058-Compiler Flags and Optimization Levels.md","filePath":"posts/c教程/zh-CN/06-编译与构建/058-Compiler Flags and Optimization Levels.md","lastUpdated":1790163617000}'),n={name:"posts/c教程/zh-CN/06-编译与构建/058-Compiler Flags and Optimization Levels.md"};function o(i,a,p,c,l,r){return e(),s("div",null,[...a[0]||(a[0]=[d(`<p>[English version](/posts/c教程/en-US/06-Compilation and Build/058-Compiler Flags and Optimization Levels)</p><p>一旦您的程序正确编译和链接，下一步就是掌握编译器标志，即控制警告、调试信息、优化和性能的开关。</p><p>使用正确的标志可以使您的 C 代码更安全、更快且更易于调试。</p><p>我们来回顾一下最重要的部分<code>gcc</code>和<code>clang</code>每个 C 开发人员都应该知道的选项。</p><h4 id="步骤1-基本编译命令" tabindex="-1">步骤1.基本编译命令 <a class="header-anchor" href="#步骤1-基本编译命令" aria-label="Permalink to &quot;步骤1.基本编译命令&quot;">​</a></h4><p>最常见的编译命令如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -o main</span></span></code></pre></div><p>这编译<code>main.c</code>进入一个名为的可执行文件<code>main</code>使用默认设置、最少警告、无优化且无调试信息。</p><p>对于认真的开发，您需要更多的控制。</p><h4 id="步骤-2-警告标志" tabindex="-1">步骤 2. 警告标志 <a class="header-anchor" href="#步骤-2-警告标志" aria-label="Permalink to &quot;步骤 2. 警告标志&quot;">​</a></h4><p>警告是编译器的预警系统。他们在错误变成错误之前发现它们。</p><table tabindex="0"><thead><tr><th>旗帜</th><th>意义</th></tr></thead><tbody><tr><td><code>-Wall</code></td><td>启用最常见的警告</td></tr><tr><td><code>-Wextra</code></td><td>启用额外的、更严格的警告</td></tr><tr><td><code>-Werror</code></td><td>将警告视为错误</td></tr><tr><td><code>-Wpedantic</code></td><td>严格遵守 ISO C</td></tr><tr><td><code>-Wshadow</code></td><td>如果局部变量隐藏另一个变量，则发出警告</td></tr><tr><td><code>-Wconversion</code></td><td>关于隐式类型转换的警告</td></tr><tr><td><code>-Wunused</code></td><td>警告未使用的变量或函数</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -Wall -Wextra -Werror main.c -o main</span></span></code></pre></div><p>如果您的代码有：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x;</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x);</span></span></code></pre></div><p>你会得到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>warning: &#39;x&#39; is used uninitialized</span></span></code></pre></div><p>和<code>-Werror</code>，该警告成为构建停止错误，这是干净代码库的好习惯。</p><h4 id="步骤-3-调试标志" tabindex="-1">步骤 3. 调试标志 <a class="header-anchor" href="#步骤-3-调试标志" aria-label="Permalink to &quot;步骤 3. 调试标志&quot;">​</a></h4><p>调试信息允许使用诸如<code>gdb</code>或者<code>lldb</code>将机器代码映射回您的 C 源代码。</p><table tabindex="0"><thead><tr><th>旗帜</th><th>描述</th></tr></thead><tbody><tr><td><code>-g</code></td><td>包括调试符号（文件名、行号）</td></tr><tr><td><code>-ggdb</code></td><td>包含 gdb 的 GNU 特定符号</td></tr><tr><td><code>-O0</code></td><td>禁用优化（使调试更容易）</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g -O0 main.c -o main</span></span></code></pre></div><p>现在运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb ./main</span></span></code></pre></div><p>您将能够检查变量并单步执行源代码行。</p><h4 id="步骤-4-优化级别" tabindex="-1">步骤 4. 优化级别 <a class="header-anchor" href="#步骤-4-优化级别" aria-label="Permalink to &quot;步骤 4. 优化级别&quot;">​</a></h4><p>优化告诉编译器如何积极地转换代码以提高速度或大小。</p><table tabindex="0"><thead><tr><th>旗帜</th><th>描述</th></tr></thead><tbody><tr><td><code>-O0</code></td><td>无需优化（编译快，调试方便）</td></tr><tr><td><code>-O1</code></td><td>基础优化</td></tr><tr><td><code>-O2</code></td><td>一般速度优化（大多数版本的默认设置）</td></tr><tr><td><code>-O3</code></td><td>积极优化（可能会增加大小）</td></tr><tr><td><code>-Os</code></td><td>优化尺寸</td></tr><tr><td><code>-Ofast</code></td><td>忽视严格的速度标准（危险）</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -O2 main.c -o main</span></span></code></pre></div><p>比较尺寸：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -O0 main.c -o slow</span></span>
<span class="line"><span>gcc -O2 main.c -o fast</span></span>
<span class="line"><span>ls -lh slow fast</span></span></code></pre></div><p><code>fast</code>当代码变得更小、运行速度更快时，编译器会重新排序代码、内联函数并删除死逻辑。</p><h4 id="步骤-5-分析和检测标志" tabindex="-1">步骤 5. 分析和检测标志 <a class="header-anchor" href="#步骤-5-分析和检测标志" aria-label="Permalink to &quot;步骤 5. 分析和检测标志&quot;">​</a></h4><p>分析有助于测量程序的哪些部分消耗了最多的 CPU 时间。</p><table tabindex="0"><thead><tr><th>旗帜</th><th>目的</th></tr></thead><tbody><tr><td><code>-pg</code></td><td>生成分析数据<code>gprof</code></td></tr><tr><td><code>-fprofile-generate</code>/<code>-fprofile-use</code></td><td>使用配置文件引导优化 (PGO)</td></tr><tr><td><code>-ftime-report</code></td><td>显示每个编译阶段花费了多长时间</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg main.c -o main</span></span>
<span class="line"><span>./main</span></span>
<span class="line"><span>gprof main gmon.out &gt; report.txt</span></span></code></pre></div><h4 id="步骤-6-标准合规标志" tabindex="-1">步骤 6. 标准合规标志 <a class="header-anchor" href="#步骤-6-标准合规标志" aria-label="Permalink to &quot;步骤 6. 标准合规标志&quot;">​</a></h4><p>C语言不断发展，您可以指定遵循哪个版本。</p><table tabindex="0"><thead><tr><th>旗帜</th><th>意义</th></tr></thead><tbody><tr><td><code>-std=c89</code></td><td>ANSI C (1989)</td></tr><tr><td><code>-std=c99</code></td><td>现代 C 与<code>inline</code>,<code>bool</code>,<code>// comments</code></td></tr><tr><td><code>-std=c11</code></td><td>添加<code>_Generic</code>,<code>_Thread_local</code>，更安全的原子</td></tr><tr><td><code>-std=c17</code></td><td>小清理</td></tr><tr><td><code>-std=c23</code></td><td>最新（添加<code>typeof</code>、更安全的宏等）</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c99 -Wall main.c -o main</span></span></code></pre></div><p>始终为您的项目选择一致的标准。</p><h4 id="步骤-7-平台和架构标志" tabindex="-1">步骤 7. 平台和架构标志 <a class="header-anchor" href="#步骤-7-平台和架构标志" aria-label="Permalink to &quot;步骤 7. 平台和架构标志&quot;">​</a></h4><table tabindex="0"><thead><tr><th>旗帜</th><th>描述</th></tr></thead><tbody><tr><td><code>-m32</code>/<code>-m64</code></td><td>针对 32 位或 64 位架构进行编译</td></tr><tr><td><code>-march=native</code></td><td>针对主机 CPU 进行优化</td></tr><tr><td><code>-fPIC</code></td><td>与位置无关的代码（共享库所需）</td></tr><tr><td><code>-static</code></td><td>完全静态链接</td></tr><tr><td><code>-DNAME=value</code></td><td>定义一个宏（与<code>#define</code>在代码中）</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -DDEBUG=1 -O2 -m64 main.c -o main</span></span></code></pre></div><h4 id="步骤-8-链接标志" tabindex="-1">步骤 8.链接标志 <a class="header-anchor" href="#步骤-8-链接标志" aria-label="Permalink to &quot;步骤 8.链接标志&quot;">​</a></h4><table tabindex="0"><thead><tr><th>旗帜</th><th>描述</th></tr></thead><tbody><tr><td><code>-L </code></td><td>添加库搜索路径</td></tr><tr><td><code>-l </code></td><td>与库的链接（例如，<code>-lm</code>数学）</td></tr><tr><td><code>-static</code></td><td>强制静态链接</td></tr><tr><td><code>-shared</code></td><td>构建共享库</td></tr><tr><td><code>-rpath </code></td><td>添加运行时库搜索路径</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -L. -lmylib -Wl,-rpath=. -o app</span></span></code></pre></div><p><code>-Wl,</code>将选项直接传递给链接器（<code>ld</code>).</p><h4 id="小代码-调试和发布版本" tabindex="-1">小代码：调试和发布版本 <a class="header-anchor" href="#小代码-调试和发布版本" aria-label="Permalink to &quot;小代码：调试和发布版本&quot;">​</a></h4><p>生成文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>DEBUG_FLAGS = -g -O0 -DDEBUG</span></span>
<span class="line"><span>RELEASE_FLAGS = -O2 -DNDEBUG</span></span>
<span class="line"><span>SRC = main.c util.c</span></span>
<span class="line"><span>OBJ = $(SRC:.c=.o)</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>debug: CFLAGS += $(DEBUG_FLAGS)</span></span>
<span class="line"><span>debug: $(TARGET)</span></span>
<span class="line"><span>release: CFLAGS += $(RELEASE_FLAGS)</span></span>
<span class="line"><span>release: $(TARGET)</span></span>
<span class="line"><span>$(TARGET): $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) $(OBJ) -o $(TARGET)</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(TARGET)</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make debug</span></span>
<span class="line"><span>make release</span></span></code></pre></div><ul><li>调试构建：完整符号，无优化。</li><li>发布版本：优化，无调试信息。</li></ul><h4 id="步骤-9-sanitizers-运行时安全工具" tabindex="-1">步骤 9. Sanitizers（运行时安全工具） <a class="header-anchor" href="#步骤-9-sanitizers-运行时安全工具" aria-label="Permalink to &quot;步骤 9. Sanitizers（运行时安全工具）&quot;">​</a></h4><p>现代编译器包含内置的清理程序来检测内存和线程错误：</p><table tabindex="0"><thead><tr><th>旗帜</th><th>检测</th></tr></thead><tbody><tr><td><code>-fsanitize=address</code></td><td>内存泄漏、缓冲区溢出</td></tr><tr><td><code>-fsanitize=undefined</code></td><td>未定义的行为</td></tr><tr><td><code>-fsanitize=thread</code></td><td>多线程代码中的数据竞争</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g -fsanitize=address main.c -o main</span></span>
<span class="line"><span>./main</span></span></code></pre></div><p>如果您的代码写入超出了数组边界，您将获得即时、可读的报告，无需猜测。</p><h4 id="步骤-10-组合标志" tabindex="-1">步骤 10. 组合标志 <a class="header-anchor" href="#步骤-10-组合标志" aria-label="Permalink to &quot;步骤 10. 组合标志&quot;">​</a></h4><p>典型的开发构建：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -Wall -Wextra -Werror -g -O0 -std=c99 main.c -o debug_app</span></span></code></pre></div><p>典型的发布版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -O2 -march=native -flto -DNDEBUG main.c -o fast_app</span></span></code></pre></div><p>-<code>-flto</code>启用链接时优化 (LTO)，跨文件进行优化。 -<code>-DNDEBUG</code>禁用<code>assert()</code>来电。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>编译器标志是专业人士控制的方式：</p><ul><li>安全（警告、消毒剂）</li><li>性能（优化级别）</li><li>可调试性（符号和检查）</li><li>可移植性（标准和架构）</li></ul><p>掌握它们可以让您精确控制代码的行为、构建和执行方式，这对于可靠的系统编程至关重要。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编译相同的程序<code>-O0</code>,<code>-O2</code>， 和<code>-O3</code>，每次运行的时间。</li><li>添加<code>-fsanitize=address</code>并找到隐藏的内存错误。</li><li>比较之间的二进制大小<code>-g</code>和<code>-s</code>. 4.添加<code>-Wall -Wextra -Werror</code>到你的 Makefile 并修复每个警告。</li><li>探索<code>gcc --help=optimizers</code>查看所有可用的优化过程。</li></ol><p>接下来，您将查看目标文件本身，了解其中存储的内容<code>.o</code>二进制文件以及链接器如何将它们拼接在一起以形成完整的可执行文件。</p>`,80)])])}const g=t(n,[["render",o]]);export{b as __pageData,g as default};
